views.mermaid:
flowchart LR
  customer["Customer<br/>Person<br/>Buys products"]
  shop["Shop<br/>Software system<br/>Takes and fulfils orders"]
  payment["Payment provider<br/>External system<br/>Authorises charges"]
  customer -->|Browses and places orders| shop
  shop -->|Requests payment authorisation| payment
  classDef person fill:#f5ead8,stroke:#80613e,color:#382a1b;
  classDef internal fill:#e2efeb,stroke:#377568,color:#173e35;
  classDef external fill:#ecece9,stroke:#777971,color:#343630;
  class customer person;
  class shop internal;
  class payment external;

flowchart LR
  customer["Customer<br/>Person<br/>Places orders"]
  subgraph shop["Shop · Software system"]
    web["Web app<br/>Container · React<br/>Checkout experience"]
    api["Orders API<br/>Container · Node.js<br/>Validates and records orders"]
    store["Orders store<br/>Container · PostgreSQL<br/>Persists orders"]
  end
  payment["Payment provider<br/>External system<br/>Authorises charges"]
  customer -->|Places order| web
  web -->|Submits order / HTTPS| api
  api -->|Writes order / SQL| store
  api -->|Authorises charge / HTTPS| payment
  classDef person fill:#f5ead8,stroke:#80613e,color:#382a1b;
  classDef internal fill:#e2efeb,stroke:#377568,color:#173e35;
  classDef external fill:#ecece9,stroke:#777971,color:#343630;
  classDef data fill:#e6edf4,stroke:#58748e,color:#253d53;
  class customer person;
  class web,api internal;
  class payment external;
  class store data;
